def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    top = {c: min(r for r in range(rows) for x in range(cols) if grid[r][x] == c) for c in colors}
    target = top[8]
    out = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for x in range(cols):
            c = grid[r][x]
            if c:
                out[r + target - top[c]][x] = c
    return out
